SELECT CAST(SUM(CASE WHEN strftime('%Y', OpenDate) = '1980' THEN 1 ELSE 0 END) AS REAL) / 12.0
FROM schools
WHERE County = 'Alameda' AND DOC = '52';

SELECT GSoffered
FROM schools
WHERE ABS(Longitude) = (SELECT MAX(ABS(Longitude)) FROM schools);

SELECT
  SUM(CASE WHEN status = 'A' THEN amount ELSE 0 END) * 100.0 / SUM(amount) AS percentage
FROM loan;

SELECT DISTINCT artist
FROM cards
WHERE setCode = 'COLD' AND artist IN ('Jeremy Jarvis', 'Aaron Miller', 'Chippy');

SELECT SUM(CASE WHEN cardKingdomFoilId IS NOT NULL AND cardKingdomId IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM cards
WHERE name = 'Coldsnap';

SELECT SUM(publisher_name = 'DC Comics') - SUM(publisher_name = 'Marvel Comics') AS difference
FROM superhero
JOIN publisher ON superhero.publisher_id = publisher.id;

SELECT player_name
FROM Player
WHERE substr(birthday, 1, 4) = '1970' AND substr(birthday, 6, 2) = '10';

SELECT DISTINCT e.type
FROM event e
WHERE e.location = 'MU 215';

SELECT SUM(CASE WHEN Country = 'CZE' THEN 1 ELSE 0 END) - SUM(CASE WHEN Country = 'SVK' THEN 1 ELSE 0 END) AS difference
FROM gasstations
WHERE Segment = 'discount';
